import{_ as a,C as e,c as i,o as r,a0 as o,b as s,w as n,a as t,G as l,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Guía de la sesión: Introducción al juego mental (2-3 horas)","description":"","frontmatter":{},"headers":[],"relativePath":"es/mental-journey/session-guide.md","filePath":"es/mental-journey/session-guide.md"}');const p=a({name:"es/mental-journey/session-guide.md"},[["render",function(a,u,p,d,m,g){const h=e("Mermaid");return r(),i("div",null,[u[1]||(u[1]=o('<h1 id="guia-de-la-sesion-introduccion-al-juego-mental-2-3-horas" tabindex="-1">Guía de la sesión: Introducción al juego mental (2-3 horas) <a class="header-anchor" href="#guia-de-la-sesion-introduccion-al-juego-mental-2-3-horas" aria-label="Permalink to &quot;Guía de la sesión: Introducción al juego mental (2-3 horas)&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción general <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción general&quot;">​</a></h2><p>Esta guía te ayuda a realizar una sesión introductoria de 2 a 3 horas sobre entrenamiento mental para jugadores de petanca. Ideal para entrenadores, líderes de club o jugadores experimentados que quieran introducir el entrenamiento mental en su equipo.</p><div class="tip custom-block"><p class="custom-block-title">Dos secciones en esta guía</p><ul><li><strong><a href="#para-participantes">Para los participantes</a></strong> - Qué aprenderán los jugadores</li><li><strong><a href="#para-facilitadores">Para facilitadores</a></strong> - Cómo llevar a cabo la sesión</li></ul></div><h2 id="acceso-rapido" tabindex="-1">Acceso rápido <a class="header-anchor" href="#acceso-rapido" aria-label="Permalink to &quot;Acceso rápido&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sección</th><th>Objetivo</th><th>Acceso</th></tr></thead><tbody><tr><td><strong>Para los participantes</strong></td><td>Qué esperar de la sesión</td><td><a href="#para-participantes">Ver sección</a></td></tr><tr><td><strong>Para facilitadores</strong></td><td>Plan completo de la sesión y cronograma</td><td><a href="#para-facilitadores">Ver sección</a></td></tr><tr><td><strong>Materiales de la sesión</strong></td><td>Guías, diapositivas y hojas de trabajo</td><td><a href="/es/mental-journey/materials">Ver materiales</a></td></tr><tr><td><strong>Lista de verificación de preparación</strong></td><td>Qué preparar antes de la sesión</td><td><a href="#preparación-1-semana-antes">Ver lista de verificación</a></td></tr></tbody></table><hr><h2 id="para-los-participantes" tabindex="-1">Para los participantes <a class="header-anchor" href="#para-los-participantes" aria-label="Permalink to &quot;Para los participantes&quot;">​</a></h2><h3 id="que-esperar" tabindex="-1">Qué esperar <a class="header-anchor" href="#que-esperar" aria-label="Permalink to &quot;Qué esperar&quot;">​</a></h3><p>Esta sesión introduce el juego mental de la petanca a través de debates, ejercicios y técnicas prácticas que podrás utilizar de inmediato.</p><p><strong>Aprenderás:</strong></p><ul><li>Por qué el entrenamiento mental es importante para el rendimiento</li><li>La diferencia entre el &quot;modo técnico&quot; y el &quot;modo de flujo&quot;</li><li>Cómo reconocer y gestionar a tu crítico interno</li><li>Técnicas sencillas para el manejo de la presión</li><li>Una rutina básica previa al disparo</li></ul><p><strong>Lo que necesitarás:</strong></p><ul><li>Mente abierta y voluntad de compartir.</li><li>Cuaderno y bolígrafo</li><li>Tus propias experiencias para discutir</li><li>2-3 horas de tiempo concentrado</li></ul><h3 id="estructura-de-la-sesion" tabindex="-1">Estructura de la sesión <a class="header-anchor" href="#estructura-de-la-sesion" aria-label="Permalink to &quot;Estructura de la sesión&quot;">​</a></h3>',15)),(r(),s(c,null,{default:n(()=>[l(h,{id:"mermaid-155",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BIntroducci%C3%B3n%20%3Cbr%2F%3E%2020%20minutos%5D%20--%3E%20B%5BLa%20Zona%20%3Cbr%2F%3E%2040%20minutos%5D%0A%20%20%20%20B%20--%3E%20C%5BRomper%20%3Cbr%2F%3E%2010%20minutos%5D%0A%20%20%20%20C%20--%3E%20D%5BCr%C3%ADtico%20interno%20%3Cbr%2F%3E%2040%20minutos%5D%0A%20%20%20%20D%20--%3E%20E%5BHerramientas%20pr%C3%A1cticas%20%3Cbr%2F%3E%2040%20minutos%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegraci%C3%B3n%20%3Cbr%2F%3E%2020%20minutos%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:n(()=>[...u[0]||(u[0]=[t(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=o('<h3 id="conceptos-clave-que-exploraras" tabindex="-1">Conceptos clave que explorarás <a class="header-anchor" href="#conceptos-clave-que-exploraras" aria-label="Permalink to &quot;Conceptos clave que explorarás&quot;">​</a></h3><h4 id="_1-la-zona-estado-de-flujo" tabindex="-1">1. La Zona (Estado de Flujo) <a class="header-anchor" href="#_1-la-zona-estado-de-flujo" aria-label="Permalink to &quot;1. La Zona (Estado de Flujo)&quot;">​</a></h4><ul><li>Lo que se siente cuando todo encaja</li><li>Por qué pensar en la técnica altera el rendimiento</li><li>El “cambio” de la planificación a la ejecución</li></ul><h4 id="_2-el-critico-interno" tabindex="-1">2. El crítico interno <a class="header-anchor" href="#_2-el-critico-interno" aria-label="Permalink to &quot;2. El crítico interno&quot;">​</a></h4><ul><li>Cómo el diálogo interno negativo afecta el rendimiento</li><li>La diferencia entre el Crítico Interno y el Coach Interno</li><li>Observación neutral vs. juicio severo</li></ul><h4 id="_3-respuesta-a-la-presion" tabindex="-1">3. Respuesta a la presión <a class="header-anchor" href="#_3-respuesta-a-la-presion" aria-label="Permalink to &quot;3. Respuesta a la presión&quot;">​</a></h4><ul><li>Por qué juegas diferente en la competición</li><li>Signos físicos de presión</li><li>Técnicas de reinicio rápido</li></ul><h4 id="_4-herramientas-practicas" tabindex="-1">4. Herramientas prácticas <a class="header-anchor" href="#_4-herramientas-practicas" aria-label="Permalink to &quot;4. Herramientas prácticas&quot;">​</a></h4><ul><li>Reinicio de 3 respiraciones</li><li>Rutina sencilla previa al disparo</li><li>Protocolo de recuperación de errores</li></ul><h3 id="que-llevar" tabindex="-1">Qué llevar <a class="header-anchor" href="#que-llevar" aria-label="Permalink to &quot;Qué llevar&quot;">​</a></h3><p><strong>Requerido:</strong></p><ul><li>Tú mismo y tus experiencias</li><li>Voluntad de participar</li></ul><p><strong>Opcional:</strong></p><ul><li>Ejemplos de desafíos mentales que enfrentas</li><li>Preguntas sobre situaciones específicas</li><li>Cuaderno para notas personales</li></ul><h3 id="despues-de-la-sesion" tabindex="-1">Después de la sesión <a class="header-anchor" href="#despues-de-la-sesion" aria-label="Permalink to &quot;Después de la sesión&quot;">​</a></h3><p>Recibirás:</p><ul><li>Resumen de conceptos clave</li><li>Ejercicios de práctica para la semana</li><li>Enlaces a módulos educativos detallados</li><li>Plantilla de objetivos para el desarrollo de juegos mentales</li></ul><hr><h2 id="para-facilitadores" tabindex="-1">Para facilitadores <a class="header-anchor" href="#para-facilitadores" aria-label="Permalink to &quot;Para facilitadores&quot;">​</a></h2><h3 id="lista-de-verificacion-de-preparacion" tabindex="-1">Lista de verificación de preparación <a class="header-anchor" href="#lista-de-verificacion-de-preparacion" aria-label="Permalink to &quot;Lista de verificación de preparación&quot;">​</a></h3><p><strong>1 semana antes:</strong></p><ul><li>[ ] Reservar habitación por 2-3 horas</li><li>[ ] Invitar de 6 a 12 participantes</li><li>[ ] Marcar páginas de materiales (ver <a href="/es/mental-journey/materiales">Materiales</a>)</li><li>[ ] Revise esta guía a fondo</li><li>[ ] Prepare un rotafolio o una pizarra blanca</li></ul><p><strong>1 día antes:</strong></p><ul><li>[ ] Confirmar asistencia</li><li>[ ] Preparar la sala (asientos en círculo)</li><li>[ ] Probar cualquier tecnología (diapositivas, etc.)</li><li>[ ] Preparar materiales</li></ul><p><strong>1 hora antes:</strong></p><ul><li>[ ] Llegar temprano</li><li>[ ] Disponer los asientos en círculo</li><li>[ ] Preparar materiales</li><li>[ ] Céntrate en ti mismo</li></ul><h3 id="su-papel-como-facilitador" tabindex="-1">Su papel como facilitador <a class="header-anchor" href="#su-papel-como-facilitador" aria-label="Permalink to &quot;Su papel como facilitador&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Importante</p><p>No eres un terapeuta ni un coach técnico. Eres un facilitador que:</p><ul><li>Discusión de guías</li><li>Crea un espacio seguro</li><li>Conecta conceptos con la experiencia.</li><li>Gestiona la dinámica de grupo</li></ul></div><p><strong>Habilidades clave:</strong></p><ul><li>escucha activa</li><li>Presencia neutral</li><li>Gestionar diferentes personalidades</li><li>Saber cuándo seguir adelante</li></ul><h3 id="plan-de-sesion-detallado" tabindex="-1">Plan de sesión detallado <a class="header-anchor" href="#plan-de-sesion-detallado" aria-label="Permalink to &quot;Plan de sesión detallado&quot;">​</a></h3><hr><h4 id="parte-1-introduccion-20-minutos" tabindex="-1">Parte 1: Introducción (20 minutos) <a class="header-anchor" href="#parte-1-introduccion-20-minutos" aria-label="Permalink to &quot;Parte 1: Introducción (20 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Crear seguridad psicológica</li><li>Establecer expectativas</li><li>Construir conexión grupal</li></ul><p><strong>Guion:</strong></p><p>Bienvenidos a todos. Esta sesión se centra en el juego mental de la petanca: los pensamientos, sentimientos y patrones que influyen en tu rendimiento.</p><p><strong>Reglas básicas:</strong></p><ol><li>Lo que se comparte aquí, se queda aquí</li><li>No juzgar las experiencias de los demás</li><li>La participación es voluntaria</li><li>No hay respuestas incorrectas</li></ol><p><strong>Ronda rápida:</strong> Nombre, cuánto tiempo has jugado, un desafío mental que enfrentas.</p><p><strong>Notas del facilitador:</strong></p><ul><li>Vaya primero a modelar la vulnerabilidad</li><li>Mantenga las presentaciones breves (1 minuto cada una)</li><li>Observar temas comunes</li><li>Validar todas las respuestas</li></ul><hr><h4 id="parte-2-la-zona-estado-de-flujo-40-minutos" tabindex="-1">Parte 2: La Zona/Estado de Flujo (40 minutos) <a class="header-anchor" href="#parte-2-la-zona-estado-de-flujo-40-minutos" aria-label="Permalink to &quot;Parte 2: La Zona/Estado de Flujo (40 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Comprender los estados de flujo</li><li>Reconocer el modo técnico frente al modo de flujo</li><li>Aprenda el concepto de &quot;cambio&quot;</li></ul><p><strong>Pregunta de apertura:</strong> Piensa en una ocasión en la que jugaste tu mejor partido de petanca. ¿Cómo te sentiste? ¿Qué fue diferente?</p><p><strong>Temas de discusión:</strong></p><ol><li>&quot;¿Cuántos de ustedes han tenido partidas en las que todo encajó?&quot;</li><li>¿En qué estabas pensando en esos momentos?</li><li>&quot;¿En qué se diferencia eso de cuando luchas?&quot;</li></ol><p><strong>Puntos clave de enseñanza:</strong></p><p>Utilice la pizarra para dibujar:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Ejercicio: El cambio (10 minutos)</strong></p><p>&quot;Practiquemos el momento del cambio:</p><ol><li>Ponerse de pie</li><li>Imagina que estás fuera del círculo: piensa en un tiro.</li><li>Toma un respiro</li><li>Da un paso adelante (en un círculo imaginario)</li><li>A medida que avanzas, deja ir el análisis.</li><li>Concéntrese sólo en un objetivo imaginario&quot;</li></ol><p><strong>Interrogar:</strong></p><ul><li>&quot;¿Qué notaste?&quot;</li><li>¿Fue fácil o difícil dejar de pensar?</li><li>&quot;¿Cómo podría aplicarse esto en juegos reales?&quot;</li></ul><hr><h4 id="parte-3-descanso-10-minutos" tabindex="-1">Parte 3: Descanso (10 minutos) <a class="header-anchor" href="#parte-3-descanso-10-minutos" aria-label="Permalink to &quot;Parte 3: Descanso (10 minutos)&quot;">​</a></h4><p><strong>Acciones del facilitador:</strong></p><ul><li>Fomentar el debate informal</li><li>Observa la energía del grupo</li><li>Prepárate para la siguiente sección</li></ul><hr><h4 id="parte-4-el-critico-interno-40-minutos" tabindex="-1">Parte 4: El crítico interno (40 minutos) <a class="header-anchor" href="#parte-4-el-critico-interno-40-minutos" aria-label="Permalink to &quot;Parte 4: El crítico interno (40 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Reconocer patrones de diálogo interno negativos</li><li>Distinguir entre el crítico interno y el entrenador interno</li><li>Practique la observación neutral</li></ul><p><strong>Apertura:</strong> Todos tenemos una voz interior que comenta sobre nuestro desempeño. A veces es útil, a veces es dura. Analicémosla.</p><p><strong>Ejercicio: Inventario del crítico interno (15 minutos)</strong></p><p>&quot;En tu papel, escribe:</p><ol><li>Lo que dice tu voz interior después de un mal lanzamiento</li><li>Lo que dice cuando estás bajo presión</li><li>&quot;Lo que dice de tus habilidades&quot;</li></ol><p><em>Da 5 minutos para escribir</em></p><p>&quot;Y ahora, ¿quién está dispuesto a compartir un ejemplo?&quot;</p><p><strong>Notas del facilitador:</strong></p><ul><li>Normalizar el diálogo interno duro</li><li>No intentes &quot;arreglar&quot; a nadie</li><li>Busque patrones comunes</li></ul><p><strong>Enseñanza: Crítico Interno vs Coach Interno (15 minutos)</strong></p><p>Dibuja dos columnas en la pizarra:</p><table tabindex="0"><thead><tr><th>Crítico interno</th><th>Entrenador interior</th></tr></thead><tbody><tr><td>&quot;¡¿Cómo pudiste perderte eso?!&quot;</td><td>&quot;Eso se fue a la izquierda&quot;</td></tr><tr><td>&quot;Siempre te ahogas&quot;</td><td>&quot;Intentémoslo de nuevo&quot;</td></tr><tr><td>&quot;Eres terrible&quot;</td><td>¿Qué puedo aprender?</td></tr></tbody></table><p><strong>Discusión:</strong></p><ul><li>&quot;¿Notas la diferencia?&quot;</li><li>¿Qué voz ayuda al rendimiento?</li><li>&quot;¿Puedes cambiar la voz?&quot;</li></ul><p><strong>Práctica: Reencuadre (10 minutos)</strong></p><p>&quot;Toma una de tus afirmaciones de Crítico Interno. ¿Cómo la diría un Coach Interno?&quot;</p><p>Comparte ejemplos.</p><hr><h4 id="parte-5-herramientas-practicas-40-minutos" tabindex="-1">Parte 5: Herramientas prácticas (40 minutos) <a class="header-anchor" href="#parte-5-herramientas-practicas-40-minutos" aria-label="Permalink to &quot;Parte 5: Herramientas prácticas (40 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Aprenda el reinicio de 3 respiraciones</li><li>Crea una rutina sencilla antes de disparar</li><li>Comprender la recuperación de errores</li></ul><p><strong>Herramienta 1: Reinicio de 3 respiraciones (10 minutos)</strong></p><p>Este es tu botón de reinicio de emergencia. Úsalo cuando sientas que aumenta la presión.</p><p><strong>Demostrar:</strong></p><ol><li>Inhale mientras cuenta hasta 4</li><li>Mantener durante 2 segundos</li><li>Exhala durante 6 segundos</li><li>Repetir 3 veces</li></ol><p>&quot;Practiquemos juntos ahora.&quot;</p><p><em>Guía al grupo a través de 3 ciclos</em></p><p><strong>Interrogar:</strong></p><ul><li>¿Qué notaste en tu cuerpo?</li><li>&quot;¿Cuándo podrías utilizar esto?&quot;</li></ul><p><strong>Herramienta 2: Rutina sencilla previa al disparo (15 minutos)</strong></p><p>&quot;Una rutina te ayuda a pasar de la planificación a la ejecución de manera consistente&quot;.</p><p><strong>Estructura básica:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Ejercicio:</strong> &quot;Crea tu propia rutina de 3 pasos. Escríbela.&quot;</p><p>Comparte ejemplos.</p><p><strong>Herramienta 3: Protocolo de recuperación de errores (15 minutos)</strong></p><p>&quot;Los jugadores de élite no cometen menos errores. Se recuperan más rápido.&quot;</p><p><strong>Protocolo de 3 pasos:</strong></p><ol><li><strong>Observar</strong> - Expresar el hecho de manera neutral (&quot;Eso se fue a la izquierda&quot;)</li><li><strong>Aprender</strong> - Extraer información (&quot;El viento era más fuerte de lo que pensaba&quot;)</li><li><strong>Reinicio</strong> - Avanzar (reinicio de 3 respiraciones, mirada hacia adelante)</li></ol><p><strong>Práctica:</strong> Piensa en un error reciente. Sigue los tres pasos.</p><hr><h4 id="parte-6-integracion-y-cierre-20-minutos" tabindex="-1">Parte 6: Integración y cierre (20 minutos) <a class="header-anchor" href="#parte-6-integracion-y-cierre-20-minutos" aria-label="Permalink to &quot;Parte 6: Integración y cierre (20 minutos)&quot;">​</a></h4><p><strong>Objetivos:</strong></p><ul><li>Consolidar el aprendizaje</li><li>Crear planes de acción</li><li>Proporcionar recursos</li></ul><p><strong>Preguntas de reflexión:</strong></p><ol><li>&quot;¿Qué conocimiento te llevas?&quot;</li><li>&quot;¿Qué cosa intentarás esta semana?&quot;</li><li>¿Qué preguntas quedan?</li></ol><p><strong>Planificación de acciones (10 minutos)</strong></p><p>&quot;En tu folleto, escribe:</p><ol><li>Una técnica que practicarás esta semana</li><li>¿Cuándo y dónde lo practicarás?</li><li>Cómo harás el seguimiento de tu progreso</li></ol><p><strong>Recursos:</strong></p><ul><li>Entregar hoja resumen</li><li>Compartir sitio web: carreau.app</li><li>Módulo de inicio recomendado: <a href="/es/educacion/la-zona/">La Zona</a></li></ul><p><strong>Círculo de cierre:</strong> &quot;Una palabra para describir cómo te sientes ahora mismo.&quot;</p><p><strong>Palabras finales:</strong> El entrenamiento mental es una habilidad como cualquier otra: requiere práctica. Empieza poco a poco, ten paciencia contigo mismo y observa los cambios. Gracias por tu apertura de hoy.</p><hr><h3 id="consejos-para-el-facilitador" tabindex="-1">Consejos para el facilitador <a class="header-anchor" href="#consejos-para-el-facilitador" aria-label="Permalink to &quot;Consejos para el facilitador&quot;">​</a></h3><h4 id="manejo-de-situaciones-dificiles" tabindex="-1">Manejo de situaciones difíciles <a class="header-anchor" href="#manejo-de-situaciones-dificiles" aria-label="Permalink to &quot;Manejo de situaciones difíciles&quot;">​</a></h4><p><strong>Si alguien domina:</strong></p><ul><li>&quot;Gracias [nombre]. Escuchemos a otros&quot;.</li><li>Utilice turnos estructurados</li></ul><p><strong>Si alguien se resiste:</strong></p><ul><li>No discutas</li><li>Esa es una perspectiva válida. ¿Qué opinan los demás?</li><li>Alinearse con su preocupación</li></ul><p><strong>Si alguien se emociona:</strong></p><ul><li>Normalizarlo</li><li>&quot;Esto toca algo real. Gracias por compartir.&quot;</li><li>No intentes arreglarlo</li></ul><p><strong>Si la discusión se estanca:</strong></p><ul><li>Utilice indicaciones específicas</li><li>Comparte tu propio ejemplo</li><li>Pasar a un ejercicio</li></ul><h4 id="gestion-de-la-energia" tabindex="-1">Gestión de la energía <a class="header-anchor" href="#gestion-de-la-energia" aria-label="Permalink to &quot;Gestión de la energía&quot;">​</a></h4><p><strong>Alta energía:</strong> Utilice ejercicios y movimiento <strong>Baja energía:</strong> Haz preguntas provocativas <strong>Dispersos:</strong> Devolver a la estructura <strong>Tiempo:</strong> Usa el humor o interrumpe</p><h3 id="post-sesion" tabindex="-1">Post-sesión <a class="header-anchor" href="#post-sesion" aria-label="Permalink to &quot;Post-sesión&quot;">​</a></h3><p><strong>Hacer un seguimiento:</strong></p><ul><li>Enviar correo electrónico de resumen dentro de las 24 horas</li><li>Incluir enlaces a recursos</li><li>Ofrecer responder preguntas</li><li>Programar sesión de seguimiento opcional</li></ul><p><strong>Autorreflexión:</strong></p><ul><li>¿Qué funcionó bien?</li><li>¿Qué cambiarías?</li><li>¿Qué te sorprendió?</li><li>¿Qué aprendiste?</li></ul><hr><h2 id="materiales" tabindex="-1">Materiales <a class="header-anchor" href="#materiales" aria-label="Permalink to &quot;Materiales&quot;">​</a></h2><ul><li><a href="/es/mental-journey/materials#guia-del-participante">Guía del participante</a></li><li><a href="/es/viaje-mental/materiales#diapositivas-del-facilitador">Diapositivas del facilitador</a></li><li><a href="/es/viaje-mental/materiales#hoja-de-resumen">Hoja de resumen</a></li><li><a href="/es/mental-journey/materials#exercise-worksheets">Hojas de ejercicios</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">¿Listo para facilitar?</p><ol><li>Revise esta guía a fondo</li><li>Descargar materiales</li><li>Practica los ejercicios tú mismo</li><li>Programa tu sesión</li><li>Confía en el proceso</li></ol></div>',140))])}]]);export{u as __pageData,p as default};
